"""webhook-publisher: publish() POST 稿件到自定义端点。MFlow 插件规范 v1。"""
import json, urllib.request


def publish(item, cfg):
    endpoint = (cfg or {}).get("endpoint")
    if not endpoint:
        return {"ok": False, "error": "config.endpoint 未配置"}
    payload = json.dumps({"title": item.get("title", ""), "slug": item.get("slug", ""),
                          "content": item.get("content", ""), "meta": item.get("meta", {})}).encode()
    req = urllib.request.Request(endpoint, data=payload,
                                 headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=30) as r:
        data = json.loads(r.read() or b"{}")
    return {"ok": True, "cms_id": data.get("id", ""), "url": data.get("url", "")}

"""readability-gate: Flesch Reading Ease scoring gate (EN only)"""
import re

def check(file_path, lang="en", config=None):
    max_score = (config or {}).get("max_score", 12)
    if lang != "en":
        return {"rc": 0, "out": f"[readability] skip (lang={lang}, only EN scored)"}
    text = open(file_path, encoding="utf-8").read()
    if text.startswith("---"):
        text = text.split("---", 2)[-1] if text.count("---") >= 2 else text
    text = re.sub(r"^#+ .*", "", text, flags=re.M)
    text = re.sub(r"```[\s\S]*?```", "", text)
    sentences = [s.strip() for s in re.split(r"[.!?]+", text) if len(s.strip()) > 5]
    words = re.findall(r"[A-Za-z]+", text)
    if not sentences or not words:
        return {"rc": 0, "out": "[readability] insufficient content"}
    syllables = sum(max(1, len(re.findall(r"[aeiouAEIOU]", w))) for w in words)
    flesch = 206.835 - 1.015 * (len(words) / len(sentences)) - 1.455 * (syllables / len(words))
    if flesch > max_score:
        return {"rc": 1, "out": f"Flesch {flesch:.1f} > {max_score} — too complex"}
    return {"rc": 0, "out": f"Flesch={flesch:.1f} <= {max_score}"}

"""link-suggester: analyze(data) -> {suggestions: [...]}"""
import json, math, re
from pathlib import Path

def analyze(data, config=None):
    text = data.get("text", "")[:3000]
    library_path = data.get("library_path", "/www/wwwroot/mflow/run/library/lovart-global")
    top = (config or {}).get("top", 5)
    t = text.lower()
    words = set(re.findall(r"[a-z0-9]{3,}", t))
    cjk = re.findall(r"[\u4e00-\u9fff]", t)
    bigrams = {"".join(cjk[i:i + 2]) for i in range(len(cjk) - 1)}
    dt = words | bigrams
    if not dt:
        return {"suggestions": [], "note": "no tokens"}
    base = Path(library_path)
    if not base.exists():
        return {"suggestions": [], "note": "library not found"}
    hits = []
    for f in base.rglob("*.md"):
        if f.name.startswith("_"):
            continue
        name_t = set(re.findall(r"[a-z0-9]{3,}", f.stem.lower()))
        overlap = len(dt & name_t)
        if overlap < 2:
            continue
        hits.append((overlap * math.log(1 + overlap), f))
    hits.sort(key=lambda x: -x[0])
    return {"suggestions": [{"slug": f.stem, "path": str(f), "relevance": round(s, 1)}
                            for s, f in hits[:top]]}
